<script setup>
import {ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'

import {bugAPI,evidenceWorkspace} from '../bugEvidence.js'
import {randomUUID} from '../uuid.js'
import {toast} from '../composables/toast.js'

const props=defineProps({input:Object,title:String}),emit=defineEmits(['close','linked','state'])
const mode=ref('new'),name=ref(''),note=ref(''),bug=ref(null),options=ref([]),preview=ref(null),loading=ref(false),busy=ref(false),error=ref(''),saved=ref(null),key=ref(''),searching=ref(false)
let generation=0,searchGeneration=0,searchTimer
async function load(){const token=++generation;preview.value=null;saved.value=null;error.value='';mode.value='new';bug.value=null;name.value=(props.title||'').slice(0,200);note.value='';key.value=randomUUID();if(!props.input)return;loading.value=true;try{const data=await bugAPI('bug-evidence/preview',props.input);if(token===generation)preview.value=data}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation)loading.value=false}}
async function search(text=''){clearTimeout(searchTimer);const token=++searchGeneration;searchTimer=setTimeout(async()=>{searching.value=true;try{const data=await bugAPI('bug-evidence/bugs?search='+encodeURIComponent(text));if(token===searchGeneration)options.value=data.map(v=>({value:v.id,label:'#'+v.id+' · '+v.title+(v.status==='closed'?'（已关闭）':'')}))}catch(e){if(token===searchGeneration)toast(e.message,'error')}finally{if(token===searchGeneration)searching.value=false}},200)}
watch(mode,value=>{error.value='';if(value==='existing')search()})
watch(()=>props.input,value=>{if(value)load();else generation++},{immediate:true})
watch(()=>[props.input,busy.value,saved.value],()=>emit('state',{dirty:!!props.input&&!saved.value,busy:busy.value}),{immediate:true})
function warn(event){if(props.input&&!saved.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',warn))
onBeforeRouteLeave(()=>!props.input||!!saved.value||(!busy.value&&confirmAction('当前关联尚未提交，离开后将丢弃填写内容。','离开关联 Bug')))
function close(){if(!busy.value){generation++;emit('close')}}
async function save(){if(busy.value||!preview.value)return;if(mode.value==='new'&&!name.value.trim()){error.value='请填写 Bug 标题';return}if(mode.value==='existing'&&!bug.value){error.value='请选择已有 Bug';return}busy.value=true;error.value='';try{saved.value=await bugAPI('bug-evidence/link',{...props.input,request_key:key.value,work_item_id:mode.value==='existing'?bug.value:0,title:mode.value==='new'?name.value.trim():'',note:note.value});emit('linked',saved.value)}catch(e){error.value=e.message+'；内容已保留，可核对后重试。'}finally{busy.value=false}}
function openBug(){evidenceWorkspace('research','#/work/'+saved.value.work_item_id);close()}
onBeforeUnmount(()=>{generation++;searchGeneration++;clearTimeout(searchTimer);window.removeEventListener('beforeunload',warn);emit('state',{dirty:false,busy:false})})

import OptionPicker from './OptionPicker.vue'

import {confirmAction} from '../shadcnFeedback.js'


import {Badge,Button,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,EmptyTitle,Field,FieldDescription,FieldError,FieldLabel,Input,Spinner,Tabs,TabsList,TabsTrigger,Textarea} from '../shadcn-ui.js'
</script>
<template><Dialog :open="!!input" @update:open="async v=>{if(!v){close()}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(620px, calc(100vw - 24px))&quot;)==='number'?(&quot;min(620px, calc(100vw - 24px))&quot;)+'px':(&quot;min(620px, calc(100vw - 24px))&quot;)}" :show-close-button="!busy" @interact-outside="e=>{if(!(!busy))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>关联 Bug</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><Empty v-if="saved"><EmptyHeader><EmptyTitle>{{'已关联 Bug #'+saved.work_item_id}}</EmptyTitle><EmptyDescription>{{''}}</EmptyDescription></EmptyHeader><EmptyContent><Button @click="close" variant="outline" size="default" type="button">继续当前操作</Button><Button @click="openBug" variant="default" size="default" type="button">查看 Bug</Button></EmptyContent></Empty><template v-else><div style="width:100%" class="relative min-w-0" :aria-busy="loading"><div v-if="loading" class="flex items-center justify-center gap-2 p-4" role="status"><Spinner/><span class="sr-only">正在读取</span></div><fieldset class="min-w-0 space-y-5" ><Tabs :model-value="mode" @update:model-value="mode=$event;"><TabsList class="h-auto! flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;new&quot;" :disabled="busy||loading">新建平台 Bug</TabsTrigger><TabsTrigger :value="&quot;existing&quot;" :disabled="busy||loading">关联已有 Bug</TabsTrigger></TabsList></Tabs><Field v-if="mode==='new'" style="margin-top:16px"><FieldLabel>Bug 标题 <span class="text-destructive">*</span></FieldLabel><Input v-model="name" :disabled="busy" aria-label="Bug 标题" :maxlength="200"/></Field><Field v-else style="margin-top:16px"><FieldLabel>选择 Bug <span class="text-destructive">*</span></FieldLabel><OptionPicker v-model="bug" :disabled="busy" placeholder="搜索 Bug 标题或编号" aria-label="关联已有 Bug" class="min-w-36" :options="options" remote-search @search="search"/></Field><Field><FieldLabel>补充说明</FieldLabel><Textarea v-model="note" :disabled="busy" placeholder="可填写复现条件；不要填写账号密码" :maxlength="1000" :rows="({minRows:2,maxRows:3}).minRows||4"/></Field><div v-if="preview" class="evidence-preview"><div><Badge variant="secondary">{{preview.kind==='test'?'执行 #'+preview.run_id:'用户选取的日志'}}</Badge><span>{{preview.service}} · {{preview.environment}}</span><Badge v-if="preview.failed_step" :variant="(&quot;red&quot;)==='red'?'destructive':'secondary'">失败步骤 {{preview.failed_step}}</Badge><Badge v-if="preview.failed_checks" :variant="(&quot;red&quot;)==='red'?'destructive':'secondary'">{{preview.failed_checks}} 项断言未通过</Badge></div><pre v-if="preview.snapshot||preview.log">{{preview.log?.excerpt||preview.snapshot}}</pre><small>摘要仅原记录操作者可见。创建或关联不会修改来源平台 Bug；回归通过后仍需人工验证。</small></div><p v-if="error" role="alert" class="evidence-error">{{error}}</p></fieldset></div></template></div><DialogFooter v-if="!saved"><Button @click="close" variant="outline" size="default" type="button" :disabled="(busy)">取消</Button><Button v-if="!preview&&!loading" @click="load" variant="outline" size="default" type="button">重新读取证据</Button><Button @click="save" variant="default" size="default" type="button" :disabled="(loading||!preview)||(busy)"><Spinner v-if="busy"/>{{mode==='new'?'创建并关联':'确认关联'}}</Button></DialogFooter></DialogContent></Dialog></template>
<style scoped>.evidence-preview{background:var(--muted);padding:12px;border-radius:var(--radius)}.evidence-preview>div{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.evidence-preview pre{max-height:140px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--mono);font-size:.75rem}small{display:block;margin-top:12px;color:var(--muted-foreground)}.evidence-error{color:var(--destructive)}</style>
